quests[46103] = { id = 46103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Infiltrators", description = "Shadowblade, we have received a raven with most troubling news.\n\nOne of our own, an ally that walked our very Hall of Shadows, is not who they seem.\n\nI believe Lilian has already begun dissecting their corpse. You'd best hurry.", completion = "You don't really know if an ally is an undead pawn under the control of a dreadlord until you carve into them a bit.", objectives = "Speak with Lilian Voss in the Hall of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46104] = { id = 46104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnid Toxicity" }
quests[46105] = { id = 46105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnid Superiority" }
quests[46106] = { id = 46106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting off the Heads", description = "Erdris Thorn was a key commander of Ravencrest's forces. To hear him confusing us for the Legion fills me with a great sadness. He will be a difficult foe to defeat.\n\nWe must stop his squad leaders from forming up for a focused assault on Bradensbrook. Defeating them should delay his forces long enough for us to find and deal with him. Let us begin our grim task.", progress = "It is difficult to bring peace to old friends.", completion = "That should disorganize the assault for some time, but we must get to the bottom of this. I sensed a fel taint about those leaders, did you?", objectives = "Slay the risen squad leaders in Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46107] = { id = 46107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Source of the Corruption", description = "There was something wrong with those three, they had a fel taint about them that was... unsettling. I believe they were somehow woken later than the other risen. Curse the Legion and their meddling!\n\nThe reinforcements are streaming out of Black Rook Hold from Heroes' Rest. We must make our way there and see if we can stop the source of these new troops.", progress = "We must end this corruption.", completion = "The attacks on Bradensbrook should relent for now. We must still deal with Lord Erdris, and soon.", objectives = "Find the source of the corruption at Heroes' Rest and end it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46108] = { id = 46108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, {class}t?", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nDeath to our enemies!", objectives = "Provide Order Resources to unlock artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46109] = { id = 46109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand!" }
quests[46110] = { id = 46110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Stormheim", description = "Your efforts have destroyed the Legion's forces upon Shield's Rest, yet they continue to press their assault.\n\nThere is only one way to end this - you must venture into the midst of our foe, find their commander, and remove his vile head!", completion = "Well done, {name}! Well done indeed!\n\nThe Legion will rue the day they set their sights on the land of Stormheim.", objectives = "Defeat Lord Commander Alexius in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46111] = { id = 46111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari Masters: Sissix" }
quests[46112] = { id = 46112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari Masters: Madam Viciosa" }
quests[46113] = { id = 46113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari Masters: Nameless Mystic" }
quests[46116] = { id = 46116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Unhallowed Grounds" }
quests[46119] = { id = 46119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boon of the Builder", objectives = "{name}! Listen. You've been real good to our business. REAL good. Never thought I'd sell so many guns.\n\nWe like to reward those that patronize our establishment, so... here. Take this.\n\nSlap this puppy on your shoulderpads and go hunting for engineering supplies. You'd be surprised how many basilisks get sprockets stuck in their gullets!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46125] = { id = 46125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furthering Knowledge", description = "We have learned so much already about these artifacts it is incredible. \n\nOur researchers have been busy preparing notes for you and with a few more resources I am sure they can be used as a crash course in gaining more artifact knowledge. \n\nThis is only the first step, with more resources we should have additional courses to help you catch up on your studies.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. The Legion must fall!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nOnward to victory!", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46126] = { id = 46126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel-Corrupted Feathers" }
quests[46127] = { id = 46127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwarting the Twins", description = "I have news from Archmage Karlain! The Kirin Tor have found Raest Magespear and can open up a portal to his location!\n\nIf you are ready to face him, I can have the mages here open the portal into the Twisting Nether.", completion = "So Raest has fallen, and in his hubris has taken his brother with him. I mourn for them both, but his brother most of all.  \n\nKaram Magespear was truly a beacon of the Light. I only hope that the stories of his sacrifices live throughout the ages. \n\nYou have done well, {name}.", objectives = "Speak with War Councilor Victoria to be teleported to Raest's location and defeat him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46128] = { id = 46128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for a Recharge", objectives = "I been thinkin' more about this whole battery thing, and how the whole process is just so... wasteful.\n\nI ain't goin' green or nothin' like that - I'm just worried about our bottom line!\n\nYou know, if one were to supercharge one of these batteries with some Blood of Sargeras, maybe cap it off with some concentrated leystone...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46129] = { id = 46129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is Power", description = "Boss, you've been working every angle on the Broken Isles, infusing that ancient artifact of yours with power. But those demons won't give up, and we really need to unlock more of your weapon's potential... and I mean pronto!\n\nSlow, steady progress is one thing. But today, we need to get busy.\n\nHere's the deal. You fork over our order's resources so I can study the weapon's history, and I'll get you a way to up the value of the power you apply to that artifact.\n\nHow does that sound, {class}t?", progress = "This is a great deal, boss! Applying the resources gathered by our order will let us make big-time progress.", completion = "Learning more about your artifact weapon will sure speed up our victory over the Legion, boss.\n\nIf you supply me with order resources, I can whip up research notes on your weapon. Read 'em, and in no time you'll be taking greater advantage of the power you infuse into your artifact.\n\nLet's do this!", objectives = "Provide Order Resources to unlock artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46130] = { id = 46130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, {class}t?", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nFor Azeroth!", objectives = "Provide Order Resources to unlock artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46131] = { id = 46131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is Power", description = "You are truly the scourge of the Broken Isles, wresting power from our enemies and infusing it into your ancient artifact. But we must not become complacent! Let us unlock further depths of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we will redouble our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact. And power is intoxicating.\n\nShall we begin, {class}t?", progress = "Applying the resources gathered by our order will allow us to make quick progress toward empowering your artifact and dominating our foes.", completion = "Knowledge of your artifact is the key to bending the demons to your will.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, Netherlord, and the power you infuse into your artifact will magnify.\n\nYour foes will quake in fear... as it should be!", objectives = "Provide Order Resources to unlock artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46132] = { id = 46132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is Power", description = "Durin' our campaign on the Broken Isles, ye have infused yer ancient artifact with power. But as the Legion invasion grows stronger, it's clear we need to unlock more of yer weapon's potential.\n\nThere's a time for slow, steady progress. But today, we'd best hasten our efforts.\n\nBy devotin' our order's resources to studyin' the weapon's history, we can rapidly enhance the value of the power ye apply to the artifact.\n\nWe best get started, {class}t!", progress = "Applyin' the resources gathered by our order will allow us to make quick progress toward learnin' about that weapon.", completion = "Learnin' more about yer artifact weapon'll help hasten our victory over tha Legion.\n\nIf ye supply me with order resources, I can provide research notes on yer weapon. Read 'em, and learn how to take greater advantage of the power ye infuse into yer artifact.\n\nFor Azeroth!", objectives = "Provide Order Resources to unlock artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46133] = { id = 46133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have cut a swath through your enemies and infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, {class}t?", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nLet pain and suffering fall upon our enemies!", objectives = "Provide Order Resources to unlock artifact knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46134] = { id = 46134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemcutter Needed" }
