quests[46173] = { id = 46173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Planning", description = "Battlelord {name}! We should discuss our next moves!", completion = "It is good to see you again, my friend.", objectives = "Meet with Odyn in Skyhold's Great Mead Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46175] = { id = 46175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolling Thunder" }
quests[46176] = { id = 46176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archmage Accosted", description = "With the barrier dispelled, Archmage Xylem is finally within reach!\n\nHopefully he'll be cooperative in returning the Iris...", objectives = "Confront Archmage Xylem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46177] = { id = 46177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Portal Away", description = "Xylem may have escaped, but a trace of his portal remains.\n\nNow that you have freed his apprentices from his corruption, I will set them to work trying to find a way to reach him.  Once I find something, I will alert the Kirin Tor.\n\nI only ask that when you do confront the Archmage, that you try to spare his life. I believe that the good man he once was still exists beneath the shadow that has taken him.\n\nFarewell, {name}.", completion = "So Xylem has been corrupted by shadow magic and has escaped with the Focusing Iris? This is not good.\n\nThe Kirin Tor will pool our efforts with those of his apprentici-- I mean, apprentices. We must track down the archmage before he does something drastic.\n\nWe will be in touch.", objectives = "Return to Archmage Kalec in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46178] = { id = 46178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiding In Plain Sight", description = "Greetings, Shadowblade.\n\nI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.\n\nYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.\n\nAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", progress = "Your blade is not yet bloody enough.", completion = "We have shown the demons why they should truly fear the darkness. Now, Lord Ravenholdt has something for you from his personal collection.", objectives = "Assassinate the infiltrating homunculi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46179] = { id = 46179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Legion" }
quests[46180] = { id = 46180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of Our Enemy" }
quests[46182] = { id = 46182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Highmountain", description = "Our defenses have grown in strength, yet the Legion continues to press their assault on Thunder Totem. There is but one way to put an end to this madness - we must strike at the heart of their forces together and bring these attacks to an end.", completion = "Our efforts today have prevailed over the Legion's presence, though let us not be remiss - our journey has only just begun.", objectives = "Defeat Fel Commander Erixtol in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
