quests[46198] = { id = 46198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gems of Destruction" }
quests[46199] = { id = 46199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azsuna", description = "The vile demon commanding the assault must be stopped. I can get us close, but once we're there I'll rely on you and your allies to help bring down the demonic forces.", completion = "With the fall of their commander the Legion's presence in Azsuna will be more manageable for our defenders to make headway. For your efforts, we may see the end of these attacks once and for all.", objectives = "Defeat Fel Commander Xeritas in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46200] = { id = 46200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Matter Resolved... For Now...", description = "You should return to the Kirin Tor. I have no doubt they will want to hear of our success. I will find Lord Erdris, and then I will contact you.", completion = "I am relieved that you have dealt with immediate threat. We barely have enough resources for the Broken Shore as it is!\n\nStill we have something for you...", objectives = "Speak with Archmage Modera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46201] = { id = 46201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Water Be Purged" }
quests[46202] = { id = 46202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 14" }
quests[46205] = { id = 46205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Conduit No More", description = "One final task remains to sever the Burning Legion's connection to other worlds.\n\nI'll provide you transportation to get you close to the source of power, but you must deliver the final blow to the conduit.", completion = "With the conduit destroyed, now may be our only chance.", objectives = "Destroy the Legion's Conduit at the Temple of a Thousand Lights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46206] = { id = 46206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of a Frightened World", description = "\"Champion! Azeroth needs our help.\"\n\n<Magni Bronzebeard's words echo in your mind, as if rising from somewhere deep and ancient. Azeroth's world soul seeks to deliver a warning to the Speaker, but some force is interfering with the message.>\n\n<Magni has urged you to travel to Sholazar Basin, the vibrant heart of frozen Northrend, to aid him.>", completion = "This warning is an ill omen indeed, {name}. It seems the fate of Azeroth is tied to that of Argus, the homeworld of the Legion.\n\nWe must uncover the Dark Titan's plan! I believe the Speaker's connection to the world soul will prove crucial to our efforts.\n\nStay vigilant, Archdruid. We must trust in Magni's guidance... and Azeroth's as well.", objectives = "Meet Magni in Sholazar Basin and hear the warning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46207] = { id = 46207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Rage", description = "I wish to extend to you a prestigious invitation.\n\nEvery year I hold a trial for my finest warrior to prove that I command the strongest in this land. I have chosen you to be my champion in this trial.\n\nShould you succeed in completing the trial, I have a prize that will be worthy of your accomplishments awaiting you at the end.\n\nTake what time you need to prepare yourself. Come back and speak with me when you're ready to begin.", progress = "I have no doubt that you will be victorious in this trial. I look forward to watching it.", completion = "That was truly a grand exposition of {class} skill. I was truly impressed at how you handled Asrea. She will be missed.\n\nBut now on to a grander event. The prize which you so rightfully deserve.", objectives = "Speak with Odyn to begin the Trial of Rage scenario. Complete the scenario and claim your prize.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46208] = { id = 46208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Godly Invitation", completion = "Battlelord {name}, I have an offer you may be interested in...", objectives = "Speak with Odyn at your order hall in Skyhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46209] = { id = 46209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flare In The Dark" }
quests[46212] = { id = 46212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Them Up" }
quests[46213] = { id = 46213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals Not Included", description = "Turalyon is safe, and we can start to fight back.\n\nFirst things first, we must secure what supplies we can from the crash.\n\nEven though we are blessed by the Light, our ships still rely on crystal technology. From powering our defenses to arming our weapons, we will need to collect as much as we can to fight back against the enemy.\n\nVenture out into the crash and retrieve what crystals you can. While you are out there, keep an eye out for Y'mera. She was separated from us, and will need help.", progress = "I hope you brought backup with you.", completion = "You brought crystals with you? Thank the Light, that's just what we need!", objectives = "Collect 10 Argunite Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46216] = { id = 46216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Congealed Corruption" }
