quests[46234] = { id = 46234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valarjar Lore Unlock 6" }
quests[46235] = { id = 46235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secured Surroundings", description = "With Lexera defeated, her band of trappers will quickly disband. Those that refuse will meet my blade.\n\nThese shores will be free of those who wish to corrupt Azeroth's wildlife.\n\nOur work here is done for now. Let us meet at Deliverance Point. There is more I wish to discuss in secured surroundings.", completion = "You've done so much so quickly here on the Broken Shore. Impressive, {name}.", objectives = "Meet Nighthuntress Syrenne at Deliverance Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46236] = { id = 46236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebound Soldiers" }
quests[46237] = { id = 46237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodbringer's Missive", description = "Warlock! We have news from Dreadscar Rift. \n\nA message arrived by raven from Mor'zul Bloodbringer, with instructions that you meet him in Dreadscar Rift immediately!", progress = "Will you not hear me out, {class}?", completion = "Our task will not be easy, but when this is over it is we who will be the true masters of Xoroth.", objectives = "Speak with Mor'zul Bloodbringer in Dreadscar Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46238] = { id = 46238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You Build It", description = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground.\n\nI will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. \n\nHere's the list of what you'll need.", progress = "Have you the necessary materials?", completion = "Excellent. This Unbending Potion should shore up the Felslate enough to hold the portal's structure, and these Chaotic Spinel crystals should focus the portal's magic nicely.\n\nI will set the mo'arg to work posthaste.", objectives = "Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46239] = { id = 46239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel to the Core", description = "While it has become relatively easy for a warlock to open a brief window into the realms of the Legion, a sustained portal requires significantly more power.\n\nFor this, we will need a power source brimming with fel energy. \n\nI know that the commanders of the Legion use powerful fel cores to control their warships. If you can defeat the commander of one of these ships, you should be able to take their core.", progress = "Do you have the core?", completion = "I sensed the fel energy emanating from the core the moment you entered Dreadscar Rift. \n\nI think this will suit our needs.", objectives = "Collect an Overcharged Fel Core from the commander of a Legion Assault on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46240] = { id = 46240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Me Fuel, Give Me Fire", description = "A powerful core will not alone be able to power the portal. Like any powerful engine, it will require fuel - though an engine of fel energy must burn life force to thrive.\n\nWe will need blood potent in magical energy to keep our fel core running and sustain our connection to Xoroth. Fortunately, I have experience in these matters, and I know just the place where we can get some.\n\nYou'll need a jar or something.", progress = "Have you bled the owlkin dry?", completion = "That's... quite a bit of blood. I am impressed, {name}.\n\nI really should just start stockpiling this stuff. It has so many uses!", objectives = "Collect 50 Owlbeast Blood from Owlbeasts within Lostlight Grotto in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46241] = { id = 46241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Minions of Hel'nurath", description = "The dreadlord Hel'nurath gifts his lieutenants with calling stones to call and bind the dreadsteeds of Xoroth to their service. I believe one such stone will help us draw out the Wrathsteed. \n\nSome Xorothian cultists have been spotted helping the Legion's efforts on the Broken Shore. It would be safe to assume their leader has one of Hel'nurath's stones.\n\nYour succubus should be able to entice the truth out of the cultists. Find one who knows of their leader's whereabouts.", objectives = "Use your Succubus' Seduction to question Xorothian Cultists within the Dark Stockades in the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46242] = { id = 46242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadlord's Calling", description = "According to the cultist, the leader you seek should be in her tower overseeing the operations in the Dark Stockades.", progress = "I trust you found the stone?", completion = "Long have I waited to get my hands on one of the dreadlord's calling stones.  Were it not for our current task, we could outfit an army with dreadsteeds.\n\nHowever, this will serve a greater purpose. With the lure of this stone, Arax'ath will not be able to restrain the Wrathsteed. So long as we can keep the portal open long enough, it will come.", objectives = "Collect a Xorothian Calling Stone from Zuriwa the Hexxer within the Dark Stockades in the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46243] = { id = 46243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrathsteed of Xoroth", description = "The time has come and the preparations have been made. When you are ready, we will tear a hole into Xoroth, and force the Arax'ath and the Wrathsteed out of hiding.\n\nFollow me to the summoning platform. From there we will initiate the ritual.\n\nPrepare yourself, {name}. This will not be an easy undertaking.", completion = "The Wrathsteed is prepared for your binding, Netherlord. It will not be easy to enslave, its will is strong.\n\nI have to say, I'm a bit jealous. Never before have I seen such a ferocious beast, our disciples have it barely held in check.", objectives = "Complete the ritual on the Summoning Platform in Dreadscar Rift to enslave the Wrathsteed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46244] = { id = 46244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cathedral of Eternal Night: Altar of the Aegis", description = "Champion, we are ready to assault the Tomb of Sargeras.\n\nI studied the writings of Aegwynn, the Guardian who defeated the Dark Titan's avatar. She said that if her wards were compromised, a failsafe could be triggered by placing the Aegis of Aggramar upon an altar in the Cathedral of Eternal Night.\n\nYou are the hero who acquired the Pillars of Creation, {name}. Gather your allies and enter the Cathedral. Be warned: Mephistroth will use all his power to stop you from placing the Aegis. You must prevail!", progress = "There is little time. Mephistroth must be defeated, and the Cathedral of the Eternal Night secured.", completion = "Mephistroth is dead and the Cathedral is secured, but the lower reaches of the Tomb remain in the hands of the Legion.\n\nThis is not the outcome we wanted, but this fight is far from over, {name}.\n\nDo not relent. Give the Legion no quarter, no place to hide. When we are ready, we will take the Tomb and drive them from Azeroth!", objectives = "Defeat Lord Mephistroth and place the Aegis of Aggramar upon the Altar of Eternal Night.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46245] = { id = 46245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begin Construction", description = "We've got the supplies. Now someone needs to decide what to do with 'em.\n\nHmm. Looks like it's your call, being the {class}t and all!\n\nTime to pick a building to focus on.", progress = "Oi! Which building should we work on?\n\nI've got deadlines to meet, mate!", completion = "Good on ya, mate! Not that there's a bad choice to be made, of course, but it's important to keep a positive attitude when surrounded by an infinite number of demons looking to kill ya.\n\nAs you gather additional supplies, come on back and I'll see they get assigned to the fortification of your choice.\n\nPhew! That was a mouthful, right? I'd say it's time for a pint.", objectives = "Use the Construction Table to donate Legionfall War Supplies to the construction of the Mage Tower, Nether Disruptor, or Command Center.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46246] = { id = 46246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike Them Down", description = "The Felstorm continues to rain demon scum upon these shores. Kil'jaeden believes his army infinite, his resources inexhaustible.\n\nWe will show him how wrong he is.\n\nCut a swath of retribution through their ranks, {class}t. Strike down demon after demon, until your weapons are bathed in their blood. And when they cry out for mercy, send them screaming back into the Nether.", progress = "Did they plead for their lives?\n\nDid they whimper as they bled away to nothingness?", completion = "I have spent a lifetime hunting the wicked and making them pay for their crimes. When I strike a demon down, I feel a measure of justice has been served.\n\nYou have been an instrument of retribution this day, Huntmaster. Had you walked a different path, you might have made a worthy Warden.", objectives = "Slay 100 demons on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46247] = { id = 46247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Broken Isles", description = "In our zeal to reclaim the Broken Shore from the Legion, we cannot allow the rest of this land to fall into the demons' foul grip.\n\nKil'jaeden has dispatched his forces across the Broken Isles, threatening the homelands of the allies you have made. You must answer their call in this hour of need.\n\nTurn back these demon assaults with haste, {class}t. The Armies of Legionfall will see that the Broken Shore remains secured.", completion = "A fine victory, Archdruid.\n\nBut do not grow complacent! Fight back against the Legion wherever they strike.", objectives = "Defeat a Legion Assault in the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46248] = { id = 46248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Self-Fulfilling Prophecy", description = "In my life, I have witnessed many visions. Some filled me with hope... others, with despair.\n\nVictory over Kil'jaeden lies within our grasp. I have foreseen it. But visions only show us where our path might lead. They require effort to become reality.\n\nThat effort falls upon your shoulders, {name}. You have done much, but more is needed. Fight on the battlefields of the Broken Shore and forge a destiny free from the Legion's grasp!", progress = "How go your efforts on the warfront?", completion = "Step by step, we march closer to victory. We must not relent!\n\nOnly through courage and persistence will we stop the insidious evil that threatens the soul of this world.", objectives = "Complete World Quests on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46249] = { id = 46249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Championing Our Cause", description = "Important work has been done by your order, {class}t. Your champions have succeeded time and again in undermining the Legion's invasion.\n\nAs we make preparations for our assault on the Tomb of Sargeras, we need to keep the demons off balance. By pressuring them at every turn, we will expose vulnerabilities that can be exploited to our advantage.\n\nSend out your order's champions, {name}. Their missions are vital to the success of our campaign... especially as our confrontation with Kil'jaeden draws closer.", completion = "Excellent work, Huntmaster! When this war is finally won, I believe I owe you and your order champions a banquet to honor your heroism.\n\nSay, that sounds like something that Odyn fellow would say. Not that I've met him myself, of course...", objectives = "Successfully complete a Legionfall mission at your Class Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46250] = { id = 46250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Out the Head...", description = "The Broken Shore swims with Legion filth, each demon deserving of a swift and merciless end.\n\nBut some are more insidious than the rest. Powerful combatants rallying others to their perfidious cause.\n\nStrike down these demon champions and you will fill the hearts of their kin with fear and doubt. Break the Legion's spirit and we will break its back.", progress = "Are they dead yet?", completion = "We must take every opportunity to shatter the will of Kil'jaeden's army.\n\nWhen they see their mightiest champions crumble to dust, they will realize that the vaunted Legion is doomed to fall.", objectives = "Slay Rare Elite Demon Commanders on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46251] = { id = 46251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shard Times", progress = "Do you have the shards? I hope you kept an accurate count. If you counted wrong, I simply can't be held responsible for the consequences.", completion = "It has been pointed out to me that I can, on occasion, get a bit carried away.\n\nThis... <clears throat> might possibly have been one of those times.\n\nA single Nethershard will suffice for my purposes. I'm certain you can put the rest to good use.\n\nLet's not speak of this again.", objectives = "Collect 2500 Nethershards on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46252] = { id = 46252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intolerable Infestation", description = "While we purge Legion filth from the Broken Shore, the fiends maintain their hold on nearby lands. Their presence can no longer be tolerated.\n\nThe fetid strongholds of Faronaar and Felsoul Hold infest Azsuna and Suramar. Choose an attack point and cut a swath through their insidious ranks.\n\nReturn to me with demon blood on your hands, then we can resume our campaign to drive Kil'jaeden from the Tomb.", progress = "Have you laid waste to the demon strongholds?", completion = "Thinning the ranks of demons in locations like Faronaar and Felsoul Hold cuts the legs out from under the Legion.\n\nKil'jaeden will fall!", objectives = "Slay 50 demons in Faronaar or Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46253] = { id = 46253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pillars of Creation", description = "Our campaign on the Broken Shore has reached a turning point. The Armies of Legionfall stand ready to breach the Tomb of Sargeras and seal the Legion's gateway to our world.\n\nThe time to strike is now, {name}.\n\nThe Aegis of Aggramar has been secured in the Cathedral. The echo of Magna Aegwynn said that the other Pillars of Creation are needed to seal the tomb. It is fitting that you have the honor of locking those ancient relics in place and closing down the Felstorm once and for all.", progress = "The Legion's invasion must be ended.", completion = "The Pillars of Creation are in place. The Tomb of Sargeras is sealed, and Aegwynn's echo is at rest.\n\n<Khadgar gestures toward the sky.>\n\nUnfortunately, we do not have that luxury.\n\nThough you won a great victory this day, there is no time for revelry. The final battle awaits us. Make ready.", objectives = "Use the Pillars of Creation to seal the Tomb of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46254] = { id = 46254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TBD" }
quests[46255] = { id = 46255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Unstable Portals Disrupted, 1 World Boss Defeated" }
quests[46256] = { id = 46256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Treasures Found, 1 Challenge Attempted" }
quests[46257] = { id = 46257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[46258] = { id = 46258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calm After the Storm", description = "You have saved the elements from the Legion's control, and for that we thank you. However, it came at a great cost to both your health and your fellow shaman. Many came back to us wounded, dragged along by their fellow shaman.\n\nWe have seen the havoc the Doomstone can wreak. It does not belong in the hands of any being, mortal or otherwise. While you were asleep, the elemental lords and I discussed its fate.\n\nBring it to Neptulon. He will explain.", progress = "We must watch over the Doomstone. Its power is too great.", completion = "You have witnessed the destruction the Doomstone can wreak firsthand. You are a trusted warden of Azeroth, but even in your hands the power caused chaos and panic amongst your people. Imagine it in the control of someone with ill intent...\n\nWe cannot let that happen.\n\nWe discussed what to do with this artifact at length while we waited for you to awaken. We considered giving it a new home in one of the elemental planes, but each one provided its own danger.\n\nThere is no safer place for it than here.", objectives = "Bring the Doomstone to Neptulon in the Maelstrom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46259] = { id = 46259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkbinder Dilemma", description = "Ah, Delas sent you. I see.\n\nIt's good she didn't come herself. It would break her heart to see what is happening to our family.\n\nA demon is defiling our dead in the ruins nearby. She's using her fel magic on our ancestors, turning them into mindless horrors that do the bidding of the Burning Legion.\n\nI can't deal with the harpies and this demon, but maybe you could help?\n\nGet rid of the darkbinder that torments our dead, and I will grant you access to whatever's left of the Moonfang family relics.", progress = "Our dead will never know peace until Darkbinder Elissath is killed.", completion = "You have my thanks, {name}. The Moonfang family has certainly seen better days.", objectives = "Kill Darkbinder Elissath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46260] = { id = 46260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meld Into the Shadows", description = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", completion = "We've been discussing your recent success, {name}. We walk the shadows, and that often goes taken for granted. But without us, the Armies of Legionfall would have a great many more powerful demons to deal with.\n\nWe do not need the fame. We reap the rewards.", objectives = "Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46261] = { id = 46261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taste of Corruption" }
quests[46262] = { id = 46262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Tadpoles!" }
quests[46263] = { id = 46263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaving Fel Webs" }
quests[46264] = { id = 46264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Eyes Are Upon Us" }
quests[46265] = { id = 46265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel and the Fawns" }
quests[46266] = { id = 46266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Slayer", description = "If you're anything like me, I'm sure you'd prefer to remain here on solid ground.\n\nUnfortunately, it is probably best to return to the Fel Hammer right away so Kor'vass can finish the repairss.", completion = "Your quick blades have proven your worth to the Illidari yet again, Slayer {name}. We will begin the repairs to the Fel Hammer immediately. \n\nWe cannot allow the Legion to catch us with our pants down again!", objectives = "Return to Kor'vas aboard the Fel Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46267] = { id = 46267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Battlelord", description = "Battlelord {name}, Odyn will want to hear the tale of your glorious victories here!\n\nI will assist you in returning to Skyhold when you are ready.", completion = "Your return is triumphant indeed, Battlelord {name}!\n\nUnder your leadership, the warriors of Skyhold are truly a force to be reckoned with!", objectives = "Talk to Odyn in Skyhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46268] = { id = 46268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Found Memento", description = "<The trinket's fine brass exterior is inlaid with intricate filigree, though much of the detail has been battered by rocks and waves. Clearing away the grime and salt encrusting the clasp, you manage to open it.\n\nIt is a compass--or was, at least. The glass face is shattered, the needle bent, unmoving.\n\nSet into the lid is a portrait. The paint is faded and waterlogged, but the subject is unmistakable: the face of a young Anduin Wrynn.>", progress = "Well met, {name}. What brings you to Stormwind this day?", completion = "<As the king examines the compass, his expression turns from recognition to sorrow.>\n\nWhen I went through my father's things and didn't find this compass, I assumed it was with him on the Broken Shore when Gul'dan...\n\n<The king's voice breaks.>", objectives = "Bring the compass to King Anduin Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46270] = { id = 46270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse me" }
quests[46272] = { id = 46272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons to the Keep", description = "Greetings, {name}.\n\nYour presence has been requested in the royal court. The crown has urgent need of you!\n\nPlease return to Stormwind at your earliest convenience.\n\nKing Greymane is anticipating your swift arrival.", completion = "You've arrived at last, Huntmaster!\n\nYou may have noticed that King Anduin is conspicuous by his absence.\n\nThis is a situation that only you can rectify.", objectives = "Meet with Genn Greymane at Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46273] = { id = 46273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Giver of Quests", description = "asdf" }
quests[46274] = { id = 46274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consoling the King", description = "Anduin hasn't been the same since you brought him his father's compass. He has become listless... distracted.\n\nWe attempted to console him, to no avail. Yesterday morning, he left the keep without so much as a word.\n\nI ordered the guards to follow him, of course. He went to pray at the cathedral, where he's remained ever since.\n\nYou brought this melancholy upon him! You must convince the boy to resume his duties. There's a war to be won!", completion = "Let me guess... Genn sent you.\n\nI wonder which he's more concerned about... my well-being, or keeping up the appearance that everything is normal?", objectives = "Look for King Anduin Wrynn inside Stormwind Cathedral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46275] = { id = 46275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Kingdom's Heart", description = "My father was a legend. He oversaw the rebuilding of Stormwind, stood toe-to-toe with dragons, led the Alliance to numerous victories.\n\nThen, one day, he was just... gone.\n\nI wear his crown, I hold his title. But I've done nothing to earn them... or the faith of my people.\n\nI've spent the war sequestered in the keep, surrounded by guards and advisors. I need to walk the streets of Stormwind, to know whether it is hope or fear that beats in the hearts of my people.\n\nI welcome your company.", completion = "They're right. They're absolutely right.", objectives = "Accompany King Anduin on his walk through Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46277] = { id = 46277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute to Mage Tower" }
quests[46278] = { id = 46278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sender", description = "You've arrived just in time!\n\nUnlike the mail as of late, I'm afraid.\n\nWe are severely understaffed, and demand is at an all-time high. We simply can't keep up!\n\nI'd love to chat, but I need help catching up before I can rest for even a moment.\n\nFirst thing's first. Several parcels of rejected mail have broken loose again; will you help me round them all up and return them to their senders?", completion = "You're an absolute natural!\n\nSay, do you mind sticking around for awhile? I could sure use a helping hand!", objectives = "Return 9 Rejected Letters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46279] = { id = 46279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zargrom" }
quests[46282] = { id = 46282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Path", description = "Now that I have seen the Broken Shore and the terror of the Burning Legion first hand, my eyes have been opened to the truth.\n\nI speak not of the unfathomable evil of the enemy, but of the bravery and sacrifice that such evil brings about in the hearts of our people.\n\nMy father once told me that every king must carry the weight of his own crown. Mine has never felt heavier than it does at this very moment...\n\nPlease take me to the place where my father died, so that I may honor his sacrifice.", completion = "You have helped me more than I can say, {name}. For that, you will always have my thanks.", objectives = "Accompany King Anduin to the Tomb of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46283] = { id = 46283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Mage Tower - Personal Reward Received" }
quests[46286] = { id = 46286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legionfall Supplies", description = "If we don't build up some respectable fortifications, we'll lose our foothold on the Broken Shore.\n\nThat ain't gonna happen on my watch, mate!\n\nWe started construction on three key structures: the Mage Tower, the Nether Disruptor, and the Command Center. Each will play a key role in helping us pound the tar out of the Burning Legion.\n\nTo make progress, we need Legionfall War Supplies... and I mean lots of 'em! You bring 'em to me, and I'll handle distribution. Got it?", progress = "Crikey! Did you bring me Legionfall War Supplies?", completion = "That's what I'm talkin' about, mate!\n\nOi! Time to get to work.", objectives = "Complete World Quests or slay Rare Elites on the Broken Shore to earn Legionfall War Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46288] = { id = 46288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everyone to the Front" }
quests[46290] = { id = 46290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Archmage", description = "With Dalaran protected once again, we can all breathe a little easier. \n\nIt is time for us to return to the Hall of the Guardian. I'm sure Meryl is anxiously awaiting word of our success.", completion = "We must not forget that this is a temporary measure. I cannot overstate the devastation that will ensue if Kathra'natir escapes... \n\nStill, thanks to you, Dalaran's teeth are sharpened once more. Well done, Archmage {name}!", objectives = "Speak to Meryl in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46291] = { id = 46291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadmines Strike Back", description = "Breanni sent you? For her, info is always free. Just don't call me a snitch.\n\nI've been hangin' around the Deadmines for years. For the most part, it's a pretty easy livin'. But a few days ago, I started hearing noises of all sorts comin' from the mines. If you want to get in unnoticed, I'll grab us a mine cart and we can get most of the way down without so much as an awkward glace in our direction.\n\nJust let me know when you're ready to head in.", progress = "I can sneak you in. Getting out might be more of a challenge.", completion = "Someone took something from Cookies' cauldron? I'll report this to Breanni immediately. It seems the Wailing Caverns was not a singular incident. There is something big going on and I feel you have unknowingly stepped into the middle of it.", objectives = "Defeat Cookies' Leftovers in the Deadmines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46292] = { id = 46292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Challenge: Deadmines", description = "The Deadmines could still use some cleaning up, seems you didn't clear the place out last time.\n\nWe'll use the ol' mine cart trick again. Cept, we're going to put some flair into it. How do you feel about fire? No? Okay, fine. Just let me know when you're ready.", progress = "I can sneak you in. Getting out might be more of a challenge.", completion = "Impressive work. Here's the supplies I promised you. I believe that shadowy figure left it behind.", objectives = "Defeat Cookies' Leftovers in the Deadmines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46293] = { id = 46293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadmines, Part Three?", description = "I've heard suspicious rumors of movement in the Deadmines. After everything you pulled off in the Wailing Caverns, you'd be the perfect person to look into this!\n\nI have a friend in Westfall. He may not look like much, but he's quick as a whip and may have more information on what is happening in Westfall. We've already dealt with the Van Cleefs... twice. So what could be making that sort of ruckus down there?", completion = "I don't know nothing about nothing! Better get going before my shiv finds your face! Don't test me, cause I ain't all that bright!\n\nOh, Breanni? Yeah, sure! She's an old friend!", objectives = "Find Marcus \"Bagman\" Brown outside the Deadmines in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46297] = { id = 46297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelming Power", description = "We will find no sanctuary on this world. Even now the full might of the Burning Legion rises to defend Argus.\n\nThe siege camp below overflows with demon filth that stand between us and the weapon trained on the Vindicaar.\n\nThey must be dealt with before it can fully charge, or Argus will be our grave.", progress = "Is the way to the weapon clear?", completion = "Now for the main weapon.", objectives = "Kill 12 demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46304] = { id = 46304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 15" }
quests[46305] = { id = 46305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorim's Flame", description = "Not too long ago, the Drekirjar and the Thorignir respected each other. This only changed when Skovald came into power. An ancient Drekirjar spirit watches over this peak, which seems to be a sacred graveyard of some sort. He is the keeper of the ceremonial flame, which happens to be exactly what we need to call down the broodmother.\n\nWhy don't we go convince him to let us take the flame? I'm sure he'll be nothing but... amiable.", progress = "Although the spirit might stand unconvinced that raising the bodies of his deceased allies for our own bidding is necessary, we could always slaughter him to get our way. Seems normal for us.", completion = "See? Totally convinced. Let's take this torch down to the beacon.", objectives = "Convince the Drekirjar Shrine-Keeper to let you take Thorim's Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46308] = { id = 46308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave a Trail" }
quests[46313] = { id = 46313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 16" }
quests[46314] = { id = 46314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance: Seeking Kor'vas", description = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city.\n\nOne of your Illidari, Kor'vas Bloodthorn, has taken to patrolling the city streets on her own to find the source behind the recent attacks.\n\nI do not entirely trust your kind, but I will concede that you have at least proved adept at your namesake. I suggest you find Kor'vas and see what she has uncovered before the Legion strikes once more.", completion = "Slayer {name}, you're a sight for sore eyes.\n\nWe need to move quickly!", objectives = "Find Kor'vas Bloodthorn in the streets of Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46315] = { id = 46315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prideful Gladiator's Leather Armor" }
quests[46316] = { id = 46316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kanrethad Ebonlocke", objectives = "I remember you, {name}. We met long ago within the Black Temple. How could I forget such power?\n\nIt seems fitting that the council chose you as its leader in my absence.\n\nRest assured, I have no desire to challenge their decision. I owe you my life.\n\nLet me serve you and the council. There is much we can learn from each other.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46317] = { id = 46317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon's Call", description = "The Legion is launching a renewed assault against the Shrine of Aviana in Hyjal!\n\nThisalee Crow is organizing a counter-offensive, she requests your presence in the Dreamgrove at once.\n\nWe will handle the offensive here. Good luck, Archdruid!", completion = "Archdruid! We don't have much time, the shrine burns as we speak!", objectives = "Speak with Thisalee Crow in the Dreamgrove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46318] = { id = 46318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of Aviana", description = "The situation is dire. The Legion is attacking the Shrine of Aviana in Hyjal, AGAIN! They must be after something specific, but I'm not sure what.\n\nUs Druids of the Talon are skilled scouts and infiltrators, but are lacking in... durability. They won't be able to hold out for long! We must go to help!", progress = "What are you waiting for?! Get to the Shrine of Aviana in Hyjal!", completion = "The Legion will pay for what we've lost today. We escaped with as many of us as we could, but too many died in vain, trying to protect the Shrine and the Idol of Aviana, which was lost anyway, thanks to that demon scum, Shadegrove.", objectives = "Assist Thisalee in the defense of the Shrine of Aviana in Hyjal, then return to her in the Dreamgrove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46319] = { id = 46319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can't Take the Sky from Me", description = "The Shrine of Aviana has fallen to the demons, and the Idol of Aviana has been stolen.\n\nThat idol acts as a link between the Druids of the Talon and the powers of flight granted to us by Aviana.\n\nThe Druids of the Talon have decided to rebuild a new shrine in a more secure location: here in the Dreamgrove.\n\nMeanwhile, I'm going to get our idol back. Meet me in Azsuna, near where we've tracked Infazzar to, if you want to help.", progress = "<Place the Corrupted Idol of Aviana on the pedestal.>", completion = "You place the Corrupted Idol of Aviana on the pedestal.", objectives = "Deal with Infazzar the Shade, and retrieve the Idol of Aviana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46320] = { id = 46320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope For a Cure", description = "Hopefully you found enough fel poison samples with which to brew a cure.\n\nLet's meet back to the Temple of Five Dawns!", completion = "Hmm let me take a look... Yes, I think I can counter these!", objectives = "Return to the Spirit of Brewmaster Blanche in the Temple of Five Dawns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46321] = { id = 46321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus' Landing Searched" }
quests[46322] = { id = 46322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pirate's Bay", description = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.\n\nWe've received word of a large cave off the main island, where powerful demons meet to plot our downfall. One of our rogues, Lilian Voss, has formulated a plan with Tethys to take care of them, but they require your aid. They are waiting for you at Dead Man's Bay in Azsuna.", completion = "Finally... my time to shine. Let's do this right.", objectives = "Meet up with Lilian Voss and Tethys at Dead Man's Bay in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46323] = { id = 46323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's the Cache?", description = "Our goal is to retrieve a cache of gunpowder which has been infused with some sort of fel power. I don't know how the pirates here acquired it, but it is more dangerous than they know. I assure you that it will be more... effective in our hands.\n\nMaster Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", progress = "Did you get it?", completion = "Yes... the gunpowder. It is the key to my plan!", objectives = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46324] = { id = 46324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Orders", description = "We must take some precautions. As soon as you assassinate the gunner, the crew will be looking for you. I had Tethys forge some orders in her handwriting that should buy us some time.\n\nPlant the orders in the marked locations. That will take care of the danger.", completion = "They left with such purpose... fools.", objectives = "Plant the False Orders in the marked locations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46325] = { id = 46325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The United Front" }
quests[46326] = { id = 46326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorach's Calling", description = "And with that, the first phase of my machination is complete. Let's return to Jorach and tell him it is time to continue.", completion = "Welcome back, Shadowblade. I assume you've retrieved the gunpowder?", objectives = "Return to Lord Jorach Ravenholdt in the Hall of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46327] = { id = 46327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bargaining with Shadows", description = "From the clues you've been able to piece together, it appears that Levia was looking to conduct a ritual in the libraries beneath Dalaran - most likely to summon this \"Agatha\" she has become so infatuated with. I'm afraid this is a little out of my area of expertise, so I'm going to have to call in a favor.\n\nI'll send for assistance from the Council of the Black Harvest. One of their warlocks will meet you in the Chamber of the Guardian to assist with your investigation.\n\nI hope we're not too late.", completion = "You are lucky that Modera contacted me for assistance. \n\nAgatha is beyond you, {class}. She is beyond any of us.", objectives = "Meet Ritssyn Flamescowl in the Chamber of the Guardian beneath Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46328] = { id = 46328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46329] = { id = 46329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46330] = { id = 46330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46331] = { id = 46331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46333] = { id = 46333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Livin' on the Ledge", completion = "Slayer {name}, I have something I would like to speak with you about when you have a moment.", objectives = "Return to the Fel Hammer and speak with Matron Mother Malevolence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46334] = { id = 46334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fel and Back", description = "Mardum has its fair share of secrets, one of which we found not too long after we took control of the Fel Hammer. It's a breeding ground of sorts, festering with fel bats.\n\nWe've been capturing the pups and trying to train them up for our efforts against the Legion.\n\nBut the other day, we caught an even greater prize, something worthy of your position, Slayer.\n\nSpeak with Kyra and she'll provide you a ride to the ledge.", completion = "Never would I have thought an adult fel bat could be tamed, but your efforts seemed to have prove otherwise. This is a promising revelation for us.\n\nBut for now, let all see what you have accomplished.", objectives = "Speak with Kyra Lightblade to secure a ride to Felwing Ledge. Then complete the Felwing Ledge scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46335] = { id = 46335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vault of the Tirisgarde", description = "Dalaran's weapons are arcane in origin, but that doesn't mean we can't try something different. \n\nOur order's vaults contain a vast store of magical devices... Why don't you take a look around and see if there's anything we can use?", progress = "Have you found anything promising?", completion = "Now that's quite the eclectic collection if I ever saw one!\n\nThese are all powerful in their own way to be sure, but none are useable for our needs. At least not in their current form.\n\nI wonder...", objectives = "Find 5 Ancient Artifacts within the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46336] = { id = 46336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Ticket", description = "Huntmaster, we've gotten word from the Lodge that there is a letter wrought from golden light sitting on one of the tables, and it's got your name on it.\n\nNo one is sure how it got there, and someone's wolf may have tried to open it and gotten a mouth full of singed fur. Seems like it's meant only for you.\n\nWe'll hold down the fort here while you investigate.", completion = "<You gingerly pick up the shimmering letter and open it.>", objectives = "Read the Golden Letter in Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46337] = { id = 46337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night of the Wilds", description = "<The letter is written in a flowing, golden script. You can practically hear Odyn's booming voice speak the words as you read it.>\n\nThe Night of the Wilds is upon us. \n\nTonight, we will feast in honor of the beasts of legend, and they will rise once more in the Fields of the Eternal Hunt.\n\nOne among us will set out into the fields to put their spirits to rest once more. \n\nMy herald awaits you, hunter, if you will join us.", completion = "<An empty saddle sits here, as if it is waiting for your new companion.\n\nYou feel a warm kinship with the beast as you recall your meeting. You know what you must do to call the Wolfhawk. You put your fingers to your lips...>", objectives = "Ask the Herald of Odyn to take you to the Fields of the Eternal Hunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46338] = { id = 46338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Creative Solution", description = "The Nightborne Soulstone may be our best hope if we can come up with a way to safely use it without Kathra'natir escaping. If he were to get loose in Dalaran...\n\nWe should consult with our friend, Ari. She will know what modifications need to be done.", progress = "Well? What did Ari think?", completion = "So word has gotten out about Ryanna already? Ha!", objectives = "Talk to Ari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46339] = { id = 46339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keymaster Orlis", description = "The Felborne insurgents appear to be guarding a teleporter pad within the glade ahead. I wonder where it leads?\n\nIt is probably safe to assume that we'll need to kill Keymaster Orlis in order to gain access.", progress = "Did you find anything?", completion = "This appears to be some sort of attunement crystal. Perfect.", objectives = "Kill Keymaster Orlis and search his body.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46340] = { id = 46340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates Are Closed", description = "Sigryn must be reached before she can confront Odyn, but our path is blocked. Odyn will close the Gates of Valor as soon as he becomes aware of Sigryn's assault. You will have to find another way into the Halls.\n\nI have no talent with portals, but your friends at the Kirin Tor seem to be very adept. Go now to them, and find a way through.\n\nI thank you for what you've done to help Sigryn this far, {class}. I only hope we can save her from herself.", completion = "So the daughter of Skovald followed in her father's footsteps? A pity, but it may have been inevitable. I believe this may be the \"fall\" the scrolls mentioned.\n\nIf this is true, there may still be hope! I will work on a way to get us into the Halls of Valor to pursue this Sigryn. I will be in touch when we find a way.\n\nIn the meantime, you have done a great service to bring her this far. I would not let that go unrewarded.", objectives = "Return to Archmage Khadgar at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46341] = { id = 46341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of Ban-Lu", description = "Oh, hello, you must be the new Grandmaster.\n\n<Master Bu squints at you and sniffs.>\n\nYou young ones have no patience these days, always running off to fight your great battles.\n\nNo time for stories, even good ones, eh?\n\nWhy don't you put your fists down for a moment and allow an old man to tell you a tale.\n\nMaybe buy an old man a drink while you are at it?", completion = "Thank you for listening, and for paying for this beverage.", objectives = "Listen to Master Bu's story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46342] = { id = 46342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Broken Peak", description = "Of course, this is no mere story. Ban-Lu served as the personal mount of each of the previous Grandmasters, accompanying them through their travels as a faithful and trusted companion.\n\nBut... he has not revealed himself since you have become Grandmaster. This is troubling.\n\nThe last time he was seen was at the Peak of Serenity, after the fall of Grandmaster Hight.\n\nIt is there that we must begin our search for him.", completion = "A senseless loss of life, and for what?\n\n<Master Bu looks heavily at the portal and shakes his head.>", objectives = "Meet Master Bu at the Peak of Serenity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46343] = { id = 46343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trail of Ban-Lu", description = "It seems a lifetime ago that Grandmaster Hight was walking these grounds. \n\nWhile Ban-Lu has served every previous Grandmaster, he and Hight were the greatest of friends.\n\nFor many years they traveled the land, connecting with its people and maintaining our fragile peace.\n\nI cannot imagine how deeply Ban-Lu must have been affected by his passing.\n\nThere must be some clues to his whereabouts around here. Look sharply.", progress = "Have you found any more clues, Grandmaster?", completion = "These old bones just need a little rest. But we appear to be one step further on our journey.\n\nThat grummle over there looks like he could use some assistance. Why don't you talk to him while I get some rest?", objectives = "Follow the trail of Ban-Lu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46344] = { id = 46344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smelly's Luckydo", description = "You! Please help! Stupid hozen stole Smelly's luckydo! \n\nNow, Smelly always unlucky. Just turned around and look, pack is on fire.\n\nNot going to put fire out because then something ELSE unlucky happen. Maybe something worse!\n\nYou beat up hozen, yes? Get back luckydo? Smelly will help you, any way he can!", progress = "Find my luckydo yet? Getting kind of hot here.", completion = "Smelly has a new idea! Leave his pack on fire!\n\nNothing else bad happen while pack on fire! Pack on fire IS Smelly's new luckydo! You keep old one.\n\nOh, you looking for big tiger? Smelly saw big glowy tiger. Went towards monastery. Smelly was helpful?", objectives = "Collect 3 parts of Smelly's Luckydo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46345] = { id = 46345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Hornet's Nest", description = "I hope you are up for an adventure. Shall we see where that teleporter goes?", completion = "I think we have stumbled upon their headquarters. Be careful in here!", objectives = "Use the teleporter pad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46346] = { id = 46346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of Ban-Lu", description = "That was good of you to assist Smelly Mountaintop, Grandmaster, and we have learned more about the fate of Ban-lu.\n\nI won't bother you with escorting me to Shado-Pan Monastery. I can manage on my own.\n\nMeet me there and we'll continue our search.", completion = "I've just begun my meditation, Grandmaster. But we may have another lead...", objectives = "Meet Master Bu at the Shado-Pan Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46347] = { id = 46347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean-up on Aisle Sha", description = "I've spoken with the Shado-pan and they are willing to give us information if we can assist them with a task of their own.\n\nSpeak with Commander Shen-Li. While you're assisting them, I shall continue to meditate.", progress = "Ooohhmmmm... Ooooohhhhmmmm...", completion = "The Shado-pan appear greatful, Grandmaster.\n\nShall we cont... what is that black residue on your foot?", objectives = "Help Commander Shen-Li with the remaining Sha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46348] = { id = 46348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The River to Ban-Lu", description = "We still do not know where Ban-Lu has gone to, but I do know who might.\n\nTo the southeast lives a jinyu, Waterspeaker Ryuli.\n\nPerhaps he has seen Ban-Lu, or can ask him to inquire with the river about where Ban-Lu has been seen recently?\n\nAll this travel has done a number on my old joints, Grandmaster. I shall rest here a bit longer, and then catch up with you later on.", completion = "Greetings. It is not every day that a Grandmaster {class} comes to visit me. How can I be of service?", objectives = "Meet with Waterspeaker Ryuli to the southeast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46349] = { id = 46349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lilies for Ryuli", description = "I have not seen Ban-Lu, but the waters will surely know where he is.\n\nThere is a flower that grows in the lakes of the mountain slopes near the Temple of the White Tiger, that only blooms in the presence of someone pure of heart.\n\nBring me six of these Moon Lilies and I shall use them to speak to the river.", progress = "How goes the Moon Lily collection, Grandmaster?", completion = "Thank you. Allow me to search for answers for you.", objectives = "Collect 6 Moon Lilies for Waterspeaker Ryuli.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46350] = { id = 46350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Ban-Lu", description = "Ah, the ripples I feel in the water are strong! The droplet does not fall far from our location.\n\nBan-Lu is quite close. \n\n<Ryuli closes his eyes and releases the lilies into the water. They drift slowly to the east.>\n\nHe waits for you now, at the bottom of the waterfall to the east.", completion = "It will be my honor to carry you on the ceremonial path from this shrine to the temple, as I have done for the Grandmasters before you.", objectives = "Find Ban-Lu at the bottom of the waterfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46351] = { id = 46351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep it Secret, Keep it Safe", description = "The shield generator you found is much more than it appears. I do not think my elders would approve of such advanced technology being shared with outlanders...\n\nAnd yet... We owe you our lives and our freedom. \n\nYou may use it, with my blessing. Just... please be discreet about its existence, Archmage {name}.", completion = "What is this?\n\nThis is not just any old shield generator - it is almost... a sentient entity...\n\nAnd it is very eager for a job to do. Yes, I think it will be quite content to work with us.", objectives = "Return to Ari in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46352] = { id = 46352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's MailArmor" }
quests[46353] = { id = 46353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Who?", description = "Greetings. I've just received word that Master Bu has returned from a long spirit journey, and is currently resting his feet at Morning Breeze Village outside of the Temple of Five Dawns.\n\nIt's been quite a long time since anyone has seen or heard from him, but he's asking to speak to you.\n\nWe will handle the situation here while you are absent, Grandmaster.", completion = "Thank you for coming, Grandmaster.", objectives = "Meet Master Bu at Morning Breeze Village outside Temple of the Five Dawns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
